import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Índice de Disposições Legais","description":"","frontmatter":{},"headers":[],"relativePath":"pt/92-法律条文索引.md","filePath":"pt/92-法律条文索引.md"}'),d={name:"pt/92-法律条文索引.md"};function s(r,e,n,c,l,m){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="indice-de-disposicoes-legais" tabindex="-1">Índice de Disposições Legais <a class="header-anchor" href="#indice-de-disposicoes-legais" aria-label="Permalink to &quot;Índice de Disposições Legais&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>92</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave Principais</td><td>índice legal, Constituição da Simbiose, lei trabalhista, lei de proteção ao consumidor, leis complementares</td></tr></tbody></table><h2 id="i-descricao-do-indice" tabindex="-1">I. Descrição do Índice <a class="header-anchor" href="#i-descricao-do-indice" aria-label="Permalink to &quot;I. Descrição do Índice&quot;">​</a></h2><p>Este índice contém os principais documentos legais atualmente em vigor e suas disposições centrais da Civilização da Simbiose da Âncora, organizados por hierarquia legal e departamento. O escopo do índice abrange a &quot;Constituição da Simbiose&quot;, a &quot;Lei Trabalhista da Simbiose&quot;, a &quot;Lei de Proteção ao Consumidor&quot;, bem como cinco leis complementares sobre educação, saúde, moradia, meio ambiente e antitruste. Cada entrada do índice lista o nome da lei, o número da disposição e um resumo do conteúdo central da disposição. Este índice é uma ferramenta de referência; para o texto completo das disposições legais e interpretações judiciais, consulte o texto oficial de cada lei.</p><h2 id="ii-constituicao-da-simbiose" tabindex="-1">II. Constituição da Simbiose <a class="header-anchor" href="#ii-constituicao-da-simbiose" aria-label="Permalink to &quot;II. Constituição da Simbiose&quot;">​</a></h2><p>A &quot;Constituição da Simbiose&quot; é a lei fundamental da Civilização da Simbiose da Âncora, com a mais alta eficácia legal, promulgada por ocasião do estabelecimento formal da civilização da simbiose.</p><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Estabelece Hengyuanzhou (Universo de Origem Wanling Hengmao) como o domínio de governança da Civilização da Simbiose da Âncora; o propósito fundamental da civilização da simbiose é alcançar a simbiose de todas as raças e a elevação dimensional cósmica</td></tr><tr><td>Artigo 2</td><td>Estabelece o anti-plunderismo como a postura fundamental da civilização; proíbe qualquer forma de cultivo de estilo plunder e plunder de recursos</td></tr><tr><td>Artigo 3</td><td>Estabelece &quot;devolver o direito de escolher o destino e a evolução a todos os seres sencientes&quot; como o conceito central da civilização</td></tr><tr><td>Artigo 4</td><td>Estabelece mais trabalho mais ganho, autocrôscimento, todos têm um caminho, todas as raças progridem juntas como as políticas básicas da civilização</td></tr><tr><td>Artigo 5</td><td>Estabelece o sistema de abertura gratuita de trezentos conjuntos de sistemas de cultivo de origem; nenhuma organização ou indivíduo pode monopolizar a autorização de transmissão dos sistemas de cultivo</td></tr><tr><td>Artigo 6</td><td>Estabelece o mecanismo de contrato de produção conjunta como o sistema básico de alocação de recursos</td></tr><tr><td>Artigo 7</td><td>Estabelece a estratégia de ativação de 20% como objetivo nacional faseado</td></tr><tr><td>Artigo 8</td><td>Estabelece o princípio baseado na realidade; o mundo real é o único mundo real, configurações fictícias não têm eficácia legal</td></tr><tr><td>Artigo 9</td><td>Estabelece o caminho de elevação dimensional de quatro estágios como a estratégia de desenvolvimento de longo prazo da civilização</td></tr><tr><td>Artigo 10</td><td>Estabelece o princípio da igualdade de todas as raças; todas as formas de vida são iguais perante a lei</td></tr><tr><td>Artigo 11</td><td>Estabelece o princípio da evolução simbiótica; a evolução individual não pode ocorrer às custas de prejudicar os direitos evolutivos de outros indivíduos ou coletivos</td></tr><tr><td>Artigo 12</td><td>Estabelece o princípio de mais trabalho mais ganho; a alocação de recursos toma a contribuição como base central</td></tr><tr><td>Artigo 13</td><td>Estabelece o princípio do autocrôscimento; respeita o direito autônomo de cada vida de escolher a evolução</td></tr><tr><td>Artigo 14</td><td>Estabelece o princípio de que todos têm um caminho; o estado tem a obrigação de fornecer a cada vida um caminho evolutivo básico e garantia de recursos</td></tr><tr><td>Artigo 15</td><td>Estabelece o princípio da sustentabilidade; todo desenvolvimento deve levar em conta a sustentabilidade da origem cósmica</td></tr><tr><td>Artigos 16-25</td><td>Estipulam os direitos básicos de todos os seres sencientes: direito de escolher a evolução, direito de obter recursos de cultivo, direito à proteção igual, direito à participação simbiótica, direito à preservação cultural, direito a recurso e apelação, direito à liberdade pessoal, direito à dignidade humana, direito à liberdade de crença, direito à liberdade de expressão</td></tr><tr><td>Artigos 26-31</td><td>Estipulam as obrigações básicas de todos os seres sencientes: obrigação de cumprir a lei, obrigação de manter a ordem simbiótica, obrigação de contribuição laboral, obrigação de proteger o meio ambiente, obrigação de respeitar os direitos dos outros, obrigação de orientar cultivadores juniores</td></tr><tr><td>Artigo 32</td><td>Estabelece o Conselho da Âncora como a mais alta autoridade, composto por representantes de todas as raças em proporção</td></tr><tr><td>Artigo 33</td><td>Estabelece o Comitê Executivo da Simbiose como o mais alto órgão administrativo</td></tr><tr><td>Artigo 34</td><td>Estabelece o Tribunal da Simbiose como o mais alto órgão judicial, exercendo independentemente o poder judicial</td></tr><tr><td>Artigo 35</td><td>Estabelece o Comitê Supervisório da Âncora como órgão supervisório independente</td></tr><tr><td>Artigo 36</td><td>Estipula o procedimento legislativo: os projetos de lei são aprovados por maioria de mais da metade do Conselho da Âncora</td></tr><tr><td>Artigo 37</td><td>Estipula o procedimento de emenda constitucional: deve ser aprovado por maioria de mais de dois terços do Conselho da Âncora e aprovado por mais da metade do referendo nacional</td></tr><tr><td>Artigo 38</td><td>Estabelece o sistema de revisão constitucional; o Tribunal da Simbiose tem o direito de declarar inválidas as leis que violam a Constituição</td></tr><tr><td>Artigo 39</td><td>Estabelece o sistema de litígio constitucional; todos os seres sencientes podem iniciar litígio diretamente com base na Constituição</td></tr><tr><td>Artigo 40</td><td>Estipula o sistema de autonomia local; cada domínio estelar e cada plano implementam autonomia dentro da estrutura constitucional</td></tr><tr><td>Artigo 41</td><td>Estabelece o sistema republicano de todas as raças; todos os grupos étnicos são iguais na civilização da simbiose e implementam autonomia regional</td></tr><tr><td>Artigo 42</td><td>Estipula o sistema econômico da civilização da simbiose: baseado em contratos de produção conjunta, múltiplas economias de propriedade se desenvolvem juntas</td></tr><tr><td>Artigo 43</td><td>Estipula o sistema de propriedade estatal e distribuição justa dos recursos de cultivo</td></tr><tr><td>Artigo 44</td><td>Estabelece o sistema de equidade educacional, garantindo o direito igual à educação de cada vida</td></tr><tr><td>Artigo 45</td><td>Estabelece o sistema universal de segurança médica</td></tr><tr><td>Artigo 46</td><td>Estabelece o sistema de segurança habitacional, garantindo o direito básico à moradia de cada vida</td></tr><tr><td>Artigo 47</td><td>Estipula os princípios básicos da interação entre planos; nenhuma viagem não autorizada entre planos sem permissão</td></tr><tr><td>Artigo 48</td><td>Estipula que a produção legítima de atividades arqueológicas é limitada a conhecimento abstrato e informação; o retorno de matéria e energia é proibido</td></tr><tr><td>Artigo 49</td><td>Estipula os princípios básicos da retrospectiva temporal; deve seguir o princípio de observação primeiro, depois intervenção limitada</td></tr><tr><td>Artigo 50</td><td>Estipula que o direito de interpretar a Constituição pertence ao Tribunal da Simbiose, e o direito de emendar a Constituição pertence ao Conselho da Âncora</td></tr></tbody></table><h2 id="iii-lei-trabalhista-da-simbiose" tabindex="-1">III. Lei Trabalhista da Simbiose <a class="header-anchor" href="#iii-lei-trabalhista-da-simbiose" aria-label="Permalink to &quot;III. Lei Trabalhista da Simbiose&quot;">​</a></h2><p>A &quot;Lei Trabalhista da Simbiose&quot; é a lei básica que regula as relações de trabalho e protege os direitos e interesses dos trabalhadores, com base no Artigo 42 da Constituição da Simbiose como base legislativa.</p><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: regular as relações de trabalho, proteger os direitos e interesses legítimos dos trabalhadores e construir relações de trabalho harmoniosas e simbióticas</td></tr><tr><td>Artigo 2</td><td>Âmbito de aplicação: todas as relações de trabalho dentro de Hengyuanzhou, incluindo trabalho material, trabalho de cultivo e trabalho criativo</td></tr><tr><td>Artigo 3</td><td>Estabelece o princípio do emprego igual para os trabalhadores; proíbe a discriminação no emprego com base em raça, gênero, nível de cultivo ou origem</td></tr><tr><td>Artigo 4</td><td>Estabelece o princípio da livre escolha de profissão para os trabalhadores; proíbe o trabalho forçado e a escravidão</td></tr><tr><td>Artigo 5</td><td>Estipula o sistema de contrato de trabalho; ao estabelecer uma relação de trabalho, deve ser celebrado um contrato de trabalho escrito</td></tr><tr><td>Artigo 6</td><td>Estipula as cláusulas necessárias do contrato de trabalho: termo do contrato, conteúdo do trabalho, remuneração do trabalho, horário de trabalho, proteção do trabalho, seguro social</td></tr><tr><td>Artigo 7</td><td>Estabelece o sistema de jornada de oito horas e o sistema de horário de trabalho de não mais de quarenta e quatro horas por semana</td></tr><tr><td>Artigo 8</td><td>Estipula restrições de horas extras: horas extras diárias não devem exceder uma hora, circunstâncias especiais não devem exceder três horas, horas extras mensais não devem exceder trinta e seis horas</td></tr><tr><td>Artigo 9</td><td>Estipula padrões de salário de horas extras: 1,5 vezes o salário para horas extras em dias úteis, 2 vezes o salário para horas extras em dias de descanso, 3 vezes o salário para horas extras em feriados legais</td></tr><tr><td>Artigo 10</td><td>Estabelece o sistema de garantia de salário mínimo; os padrões de salário mínimo são formulados por cada domínio estelar de acordo com as condições locais</td></tr><tr><td>Artigo 11</td><td>Estipula o sistema de pagamento de salários: os salários devem ser pagos mensalmente aos próprios trabalhadores em forma monetária, e não devem ser deduzidos ou inadimplidos sem motivo</td></tr><tr><td>Artigo 12</td><td>Estabelece o princípio de distribuição de mais trabalho mais ganho; implementa um sistema de distribuição com a distribuição de acordo com o trabalho como corpo principal e múltiplos métodos de distribuição coexistindo</td></tr><tr><td>Artigo 13</td><td>Estipula o sistema de segurança e saúde no trabalho; os empregadores devem fornecer aos trabalhadores condições de segurança e saúde no trabalho que atendam aos padrões</td></tr><tr><td>Artigo 14</td><td>Estipula proteção a grupos especiais: proteção trabalhista especial para trabalhadores menores, trabalhadoras mulheres, trabalhadores com deficiência e trabalhadores de baixo cultivo</td></tr><tr><td>Artigo 15</td><td>Estabelece o sistema de treinamento profissional; os empregadores têm a obrigação de realizar treinamento de habilidades profissionais para os trabalhadores</td></tr><tr><td>Artigo 16</td><td>Estipula os direitos e interesses trabalhistas dos cultivadores: o trabalho de cultivo também é protegido por esta lei; a propriedade dos resultados do cultivo é acordada por contrato</td></tr><tr><td>Artigo 17</td><td>Estabelece o sistema de seguro social dos trabalhadores: seguro de pensão, seguro médico, seguro de desemprego, seguro de acidente de trabalho, seguro de maternidade</td></tr><tr><td>Artigo 18</td><td>Estipula o sistema de bem-estar dos trabalhadores: os empregadores devem fornecer benefícios de bem-estar necessários aos trabalhadores</td></tr><tr><td>Artigo 19</td><td>Estabelece o sistema de tratamento de disputas trabalhistas: mecanismo de tratamento de quatro níveis de negociação, mediação, arbitragem e litígio</td></tr><tr><td>Artigo 20</td><td>Estipula o sistema de sindicatos; os trabalhadores têm o direito de organizar e participar de sindicatos de acordo com a lei para salvaguardar seus direitos e interesses legítimos</td></tr><tr><td>Artigo 21</td><td>Estipula o sistema de contrato coletivo; os sindicatos representam os funcionários na celebração de contratos coletivos com os empregadores</td></tr><tr><td>Artigo 22</td><td>Estipula que as regras e regulamentos dos empregadores devem ser discutidos pelo congresso de representantes dos funcionários ou por todos os funcionários</td></tr><tr><td>Artigo 23</td><td>Estipula as condições e procedimentos para a rescisão de contratos de trabalho</td></tr><tr><td>Artigo 24</td><td>Estipula o sistema de compensação econômica; os empregadores devem pagar compensação econômica ao rescindir contratos de trabalho de acordo com a lei</td></tr><tr><td>Artigo 25</td><td>Estipula o sistema de indenização por rescisão ilegal de contrato de trabalho</td></tr><tr><td>Artigo 26</td><td>Estabelece o sistema de gerenciamento de destacamento de mão de obra, regulamentando o emprego de destacamento de mão de obra</td></tr><tr><td>Artigo 27</td><td>Estipula regras especiais para emprego de meio período</td></tr><tr><td>Artigo 28</td><td>Estipula o sistema de supervisão e inspeção; os departamentos administrativos do trabalho supervisionam e inspecionam o cumprimento das leis e regulamentos trabalhistas pelos empregadores de acordo com a lei</td></tr><tr><td>Artigo 29</td><td>Estipula responsabilidades legais: os empregadores que violarem esta lei assumirão responsabilidades administrativas, civis e criminais de acordo com a lei</td></tr><tr><td>Artigo 30</td><td>Estipula a data de entrada em vigor e o direito de interpretação desta lei</td></tr></tbody></table><h2 id="iv-lei-de-protecao-ao-consumidor" tabindex="-1">IV. Lei de Proteção ao Consumidor <a class="header-anchor" href="#iv-lei-de-protecao-ao-consumidor" aria-label="Permalink to &quot;IV. Lei de Proteção ao Consumidor&quot;">​</a></h2><p>A &quot;Lei de Proteção ao Consumidor&quot; é a lei básica que protege os direitos e interesses legítimos dos consumidores e regulamenta o comportamento dos operadores de negócios.</p><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: proteger os direitos e interesses legítimos dos consumidores, manter a ordem socioeconômica e promover o desenvolvimento saudável da economia de mercado da simbiose</td></tr><tr><td>Artigo 2</td><td>Âmbito de aplicação: proteção dos direitos e interesses dos consumidores dentro de Hengyuanzhou que compram, usam bens ou recebem serviços para necessidades de consumo diário</td></tr><tr><td>Artigo 3</td><td>Estabelece os princípios básicos das transações entre operadores de negócios e consumidores: voluntariedade, igualdade, justiça, honestidade e crédito</td></tr><tr><td>Artigo 4</td><td>Estabelece o princípio da proteção estatal dos direitos e interesses legítimos dos consumidores; o estado toma medidas para garantir que os consumidores exerçam seus direitos de acordo com a lei</td></tr><tr><td>Artigo 5</td><td>Estipula nove direitos básicos dos consumidores: direito à segurança, direito à informação, direito à escolha independente, direito à negociação justa, direito a indenização, direito de associação, direito a adquirir conhecimento, direito a ser respeitado, direito de supervisão</td></tr><tr><td>Artigo 6</td><td>Estipula o direito à segurança dos consumidores: os consumidores desfrutam do direito de que a segurança pessoal e patrimonial não seja prejudicada ao comprar, usar bens e receber serviços</td></tr><tr><td>Artigo 7</td><td>Estipula o direito à informação dos consumidores: os consumidores desfrutam do direito de conhecer a situação real dos bens que compram ou usam ou dos serviços que recebem</td></tr><tr><td>Artigo 8</td><td>Estipula o direito à escolha independente dos consumidores: os consumidores desfrutam do direito de escolher independentemente bens ou serviços</td></tr><tr><td>Artigo 9</td><td>Estipula o direito à negociação justa dos consumidores: os consumidores desfrutam do direito à negociação justa e têm o direito de recusar comportamentos de negociação forçada</td></tr><tr><td>Artigo 10</td><td>Estipula o direito a indenização dos consumidores: os consumidores que sofrem danos pessoais ou patrimoniais devido à compra, uso de bens ou recebimento de serviços desfrutam do direito de obter indenização de acordo com a lei</td></tr><tr><td>Artigo 11</td><td>Estipula obrigações básicas dos operadores de negócios: cumprir obrigações legais e contratuais, aceitar supervisão, garantir segurança, fornecer informações verdadeiras, emitir vouchers, garantir qualidade, cumprir três garantias, não realizar negociação injusta, não infringir personalidade</td></tr><tr><td>Artigo 12</td><td>Estipula a obrigação de garantia de segurança dos operadores de negócios: os operadores de negócios devem garantir que os bens ou serviços que fornecem atendam aos requisitos de proteção da segurança pessoal e patrimonial</td></tr><tr><td>Artigo 13</td><td>Estipula a obrigação de divulgação de informações dos operadores de negócios: os operadores de negócios devem fornecer aos consumidores informações verdadeiras sobre bens ou serviços, e não devem fazer publicidade falsa ou enganosa</td></tr><tr><td>Artigo 14</td><td>Estipula normas especiais para produtos e serviços de cultivo: os operadores de negócios de métodos de cultivo, instrumentos de cultivo e produtos de energia devem ter qualificações especiais, e os produtos devem passar por certificação de segurança</td></tr><tr><td>Artigo 15</td><td>Estipula a regulamentação de cláusulas padrão: os operadores de negócios não podem excluir ou limitar os direitos dos consumidores, reduzir ou isentar as responsabilidades dos operadores de negócios por meio de cláusulas padrão</td></tr><tr><td>Artigo 16</td><td>Estipula o sistema de devolução sem motivo de sete dias: os consumidores que compram bens por métodos remotos, como a Internet, têm o direito de devolver os bens dentro de sete dias a partir da data de recebimento dos bens</td></tr><tr><td>Artigo 17</td><td>Estipula o sistema de três garantias: se os bens ou serviços fornecidos pelos operadores de negócios não atenderem aos requisitos de qualidade, os consumidores podem exigir reparo, substituição ou devolução de acordo com os regulamentos estatais</td></tr><tr><td>Artigo 18</td><td>Estipula o sistema de indenização punitiva: se os operadores de negócios tiverem comportamento fraudulento no fornecimento de bens ou serviços, eles devem aumentar a indenização pelas perdas sofridas pelos consumidores de acordo com os requisitos dos consumidores, e o valor da indenização aumentada deve ser três vezes o preço dos bens comprados pelos consumidores ou o custo dos serviços recebidos</td></tr><tr><td>Artigo 19</td><td>Estipula organizações de consumidores: associações de consumidores e outras organizações de consumidores são organizações sociais estabelecidas de acordo com a lei que realizam supervisão social sobre bens e serviços para proteger os direitos e interesses legítimos dos consumidores</td></tr><tr><td>Artigo 20</td><td>Estipula canais de resolução de disputas de consumo: negociação e liquidação com operadores de negócios, solicitação de mediação da associação de consumidores, apelação a departamentos administrativos relevantes, solicitação de arbitragem, apresentação de ação ao tribunal</td></tr><tr><td>Artigo 21</td><td>Estipula a inversão do ônus da prova em disputas: para bens duráveis ou serviços como decoração, se os consumidores encontrarem defeitos dentro de seis meses a partir da data de aceitação, o operador de negócios assume o ônus da prova</td></tr><tr><td>Artigo 22</td><td>Estipula as responsabilidades administrativas e criminais dos operadores de negócios</td></tr><tr><td>Artigo 23</td><td>Estipula a data de entrada em vigor e o direito de interpretação desta lei</td></tr></tbody></table><h2 id="v-cinco-leis-complementares" tabindex="-1">V. Cinco Leis Complementares <a class="header-anchor" href="#v-cinco-leis-complementares" aria-label="Permalink to &quot;V. Cinco Leis Complementares&quot;">​</a></h2><h3 id="_5-1-lei-de-seguranca-educacional" tabindex="-1">5.1 Lei de Segurança Educacional <a class="header-anchor" href="#_5-1-lei-de-seguranca-educacional" aria-label="Permalink to &quot;5.1 Lei de Segurança Educacional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: garantir o direito igual à educação de todos os seres sencientes, construir um sistema educacional simbiótico e promover o desenvolvimento comum das culturas de todas as raças</td></tr><tr><td>Artigos 2-5</td><td>Estabelecem o princípio da equidade educacional, o princípio da educação gratuita (fase da educação básica), o princípio da diversidade educacional, o princípio da inovação educacional</td></tr><tr><td>Artigos 6-10</td><td>Estipulam a arquitetura do sistema de educação pré-escolar, educação obrigatória, educação do ensino médio, educação superior, educação de cultivo</td></tr><tr><td>Artigos 11-15</td><td>Estipulam sistemas especiais para educação de cultivo: normas de ensino para trezentos conjuntos de sistemas, sistema de mentores, sistema de alocação de recursos de cultivo</td></tr><tr><td>Artigos 16-20</td><td>Estipulam direitos e obrigações dos professores, sistema de qualificação de professores, garantia de tratamento dos professores</td></tr><tr><td>Artigos 21-25</td><td>Estipulam garantia de investimento educacional, construção de instalações educacionais, informatização educacional, educação especial, educação entre raças</td></tr><tr><td>Artigos 26-30</td><td>Estipulam sistema de avaliação educacional, sistema de supervisão educacional, responsabilidades legais e disposições complementares</td></tr></tbody></table><h3 id="_5-2-lei-de-seguranca-medica" tabindex="-1">5.2 Lei de Segurança Médica <a class="header-anchor" href="#_5-2-lei-de-seguranca-medica" aria-label="Permalink to &quot;5.2 Lei de Segurança Médica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: estabelecer um sistema universal de segurança médica, garantir o direito à saúde de todos os seres sencientes e melhorar o nível geral de saúde de todas as raças</td></tr><tr><td>Artigos 2-5</td><td>Estabelecem o princípio do seguro médico universal, o princípio da medicina básica gratuita, o princípio da integração da medicina chinesa e ocidental, o princípio da inclusão da medicina de cultivo</td></tr><tr><td>Artigos 6-10</td><td>Estipulam o sistema de seguro médico de vários níveis de seguro médico básico, seguro de doenças graves, assistência médica, seguro saúde comercial</td></tr><tr><td>Artigos 11-15</td><td>Estipulam gerenciamento de instituições médicas, sistema de pessoal médico, qualidade e segurança médica, normas especiais para medicina de cultivo</td></tr><tr><td>Artigos 16-20</td><td>Estipulam gerenciamento de medicamentos, gerenciamento de dispositivos médicos, gerenciamento de produtos médicos de energia, sistema de medicamentos essenciais</td></tr><tr><td>Artigos 21-25</td><td>Estipulam sistema de saúde pública, prevenção e controle de doenças, educação em saúde, medicina entre raças, segurança médica de grupos especiais</td></tr><tr><td>Artigos 26-30</td><td>Estipulam tratamento de disputas médicas, supervisão médica, responsabilidades legais e disposições complementares</td></tr></tbody></table><h3 id="_5-3-lei-de-seguranca-habitacional" tabindex="-1">5.3 Lei de Segurança Habitacional <a class="header-anchor" href="#_5-3-lei-de-seguranca-habitacional" aria-label="Permalink to &quot;5.3 Lei de Segurança Habitacional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: garantir o direito básico à moradia de todos os seres sencientes, construir um sistema de segurança habitacional de vários níveis e alcançar moradia para todos</td></tr><tr><td>Artigos 2-5</td><td>Estabelecem o princípio da garantia do direito à moradia, o princípio da equidade habitacional, o princípio do aluguel e compra simultâneos, o princípio da moradia sustentável</td></tr><tr><td>Artigos 6-10</td><td>Estipulam o sistema de fornecimento habitacional de moradia pública de aluguel, moradia de aluguel acessível, moradia de propriedade compartilhada, moradia comercial</td></tr><tr><td>Artigos 11-15</td><td>Estipulam sistema de fundo de previdência habitacional, sistema de subsídio habitacional, política de apoio à primeira moradia, política habitacional especial para cultivadores</td></tr><tr><td>Artigos 16-20</td><td>Estipulam padrões de construção habitacional, aplicação de tecnologia espacial na moradia, edifícios verdes, moradia adequada para idosos e sem barreiras</td></tr><tr><td>Artigos 21-25</td><td>Estipulam regulação do mercado imobiliário, regulamentação do mercado de aluguel habitacional, gerenciamento de serviços de propriedade, garantia de manutenção habitacional</td></tr><tr><td>Artigos 26-30</td><td>Estipulam supervisão de segurança habitacional, responsabilidades legais e disposições complementares</td></tr></tbody></table><h3 id="_5-4-lei-de-protecao-ambiental" tabindex="-1">5.4 Lei de Proteção Ambiental <a class="header-anchor" href="#_5-4-lei-de-protecao-ambiental" aria-label="Permalink to &quot;5.4 Lei de Proteção Ambiental&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: proteger e melhorar o meio ambiente, prevenir e controlar a poluição e outros males públicos, garantir a saúde pública, promover a construção da civilização ecológica cósmica e promover o desenvolvimento sustentável</td></tr><tr><td>Artigos 2-5</td><td>Estabelecem o princípio da prioridade da proteção, o princípio da prevenção em primeiro lugar, o princípio do tratamento abrangente, o princípio da participação pública, o princípio da responsabilidade por danos</td></tr><tr><td>Artigos 6-10</td><td>Estipulam sistema de supervisão e gerenciamento ambiental, sistema de padrões ambientais, sistema de avaliação de impacto ambiental, sistema de monitoramento ambiental, gerenciamento ambiental entre planos</td></tr><tr><td>Artigos 11-15</td><td>Estipulam prevenção e controle da poluição do ar, prevenção e controle da poluição da água, prevenção e controle da poluição do solo, prevenção e controle da poluição por energia, prevenção e controle da poluição por lei</td></tr><tr><td>Artigos 16-20</td><td>Estipulam tratamento de resíduos sólidos, prevenção e controle da poluição sonora, prevenção e controle da poluição radioativa, proteção ecológica, proteção da biodiversidade</td></tr><tr><td>Artigos 21-25</td><td>Estipulam controle de impacto ambiental de atividades de cultivo, proteção ecológica da mineração de energia, requisitos ambientais para arqueologia entre planos</td></tr><tr><td>Artigos 26-30</td><td>Estipulam divulgação de informações e participação pública, litígio de interesse público ambiental, responsabilidades legais e disposições complementares</td></tr></tbody></table><h3 id="_5-5-lei-antitruste" tabindex="-1">5.5 Lei Antitruste <a class="header-anchor" href="#_5-5-lei-antitruste" aria-label="Permalink to &quot;5.5 Lei Antitruste&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Número da Disposição</th><th>Conteúdo Central</th></tr></thead><tbody><tr><td>Artigo 1</td><td>Finalidade legislativa: prevenir e impedir comportamentos monopolistas, proteger a concorrência justa do mercado, melhorar a eficiência da operação econômica, salvaguardar os interesses dos consumidores e o interesse público social e promover o desenvolvimento saudável da economia de mercado da simbiose</td></tr><tr><td>Artigos 2-5</td><td>Estabelecem a posição básica da política de concorrência, sistema de revisão de concorrência justa, proibição de acordos monopolistas, proibição de abuso de posição dominante no mercado, controle de concentração de operadores de negócios</td></tr><tr><td>Artigos 6-10</td><td>Estipulam identificação e isenção de acordos monopolistas, acordos monopolistas horizontais, acordos monopolistas verticais, comportamento monopolista de associações industriais</td></tr><tr><td>Artigos 11-15</td><td>Estipulam identificação de posição dominante no mercado, tipos de comportamento de abuso de posição dominante no mercado, proibição de preços predatórios</td></tr><tr><td>Artigos 16-20</td><td>Estipulam padrões de declaração de concentração de operadores de negócios, procedimentos de revisão, condições restritivas adicionais, decisões de proibição de concentração</td></tr><tr><td>Artigos 21-25</td><td>Estipulam proibição especial de monopólio de sistema de cultivo: proibição de monopolizar métodos de cultivo, proibição de monopólio de recursos de cultivo, proibição de monopólio de rede de mentores</td></tr><tr><td>Artigos 26-30</td><td>Estipulam agências de aplicação da lei antitruste, procedimentos de investigação, responsabilidades legais, sistema de clemência e disposições complementares</td></tr></tbody></table><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O índice de disposições legais é um mapa de referência do sistema de estado de direito da Civilização da Simbiose da Âncora. Desde a Constituição da Simbiose como lei fundamental, até a Lei Trabalhista e a Lei de Proteção ao Consumidor que regulamentam a vida das pessoas, e depois as cinco leis complementares, elas constituem juntas um sistema legal completo &quot;com a Constituição como comandante, as leis básicas como espinha dorsal e as leis complementares como suporte&quot;. Este sistema garante que todas as atividades da civilização da simbiose operem na trilha do estado de direito, fornecendo uma garantia institucional sólida para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-Esboço Geral da Constituição da Simbiose</li><li>41-Lei Trabalhista da Simbiose</li><li>48-Sistema Judicial e Mecanismo de Adjudicação</li></ul>',28)])])}const g=o(d,[["render",s]]);export{p as __pageData,g as default};
